security.scholarship_admit_from_provider.def:
CREATE OR REPLACE FUNCTION security.scholarship_admit_from_provider_page_v1(p_candidate_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'scholarship', 'pipeline', 'catalogue', 'pim', 'security'
AS $function$
declare c record; d record; f jsonb; v_name text; v_url text; v_norm text; v_key text; v_id uuid; v_src uuid; v_ev uuid; v_dup uuid; v_dup_sa boolean; v_apply jsonb; r jsonb;
begin
  select * into c from pipeline.scholarship_page_candidates where id=p_candidate_id for update;
  if c.id is null then return jsonb_build_object('admitted',false,'reason','no candidate'); end if;
  if c.admitted_scholarship_id is not null or c.matched_scholarship_id is not null then return jsonb_build_object('admitted',false,'reason','already handled'); end if;
  select * into d from pipeline.scholarship_discovery_providers where provider_id=c.provider_id;
  f:=c.facts; v_name:=btrim(f->'admission'->>'name'); v_url:=coalesce(c.final_url,c.url); v_norm:=security.scholarship_url_norm(v_url);
  -- the rules, checked again here from the recorded page facts
  if c.read_status is distinct from 'read' or c.storage_path is null then r:=jsonb_build_object('admitted',false,'reason','page not read');
  elsif not security.scholarship_university(c.provider_id) then r:=jsonb_build_object('admitted',false,'reason','not a university provider in a scholarship country');
  elsif not security.url_on_provider_sites(v_url, c.provider_id) or security.reference_url_has_use(v_url, 'scholarship_placeholder') then r:=jsonb_build_object('admitted',false,'reason','not on the provider site');
  elsif coalesce(v_name,'')='' or length(v_name)<8 or v_name !~* '(scholarship|bursary|award|grant|fee (remission|reduction|waiver|discount)|tuition (discount|reduction|waiver))' then r:=jsonb_build_object('admitted',false,'reason','no named scholarship title');
  elsif coalesce((f->'admission'->>'detail_page')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not a single scholarship page');
  elsif coalesce((f->'admission'->>'international_explicit')::boolean,false) is not true or coalesce((f->>'international')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not explicitly open to international students');
  elsif coalesce((f->'admission'->>'offered')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','not currently offered');
  elsif coalesce((f->'admission'->>'admit')::boolean,false) is not true then r:=jsonb_build_object('admitted',false,'reason','page rules not met');
  end if;
  if r is not null then
    update pipeline.scholarship_page_candidates set admit_status='rejected', admit_reasons=array[r->>'reason'] where id=c.id;
    insert into pipeline.scholarship_admission_log(candidate_id,provider_id,action,detail) values (c.id,c.provider_id,'rejected',r);
    return r;
  end if;
  -- already held: same page, or same name at this provider
  select s.id, security.reference_url_has_use(s.source_url, 'scholarship_placeholder') into v_dup, v_dup_sa from scholarship.scholarships s
   where s.provider_id=c.provider_id and s.lifecycle_status='active'
     and (security.scholarship_url_norm(s.source_url)=v_norm or scholarship.normalise_title(s.name)=scholarship.normalise_title(v_name)
          or exists (select 1 from scholarship.identifiers i where i.scholarship_id=s.id and i.scheme='first_party_detail_url' and security.scholarship_url_norm(i.identifier_value) in (v_norm, c.url_norm))
          or exists (select 1 from pipeline.scholarship_pages sp where sp.scholarship_id=s.id and security.scholarship_url_norm(sp.url) in (v_norm, c.url_norm)))
   order by (security.reference_url_has_use(s.source_url, 'scholarship_placeholder')) limit 1;
  if v_dup is not null then
    if v_dup_sa and not exists (select 1 from pipeline.scholarship_pages where scholarship_id=v_dup) then
      -- a held Study Australia-only scholarship named by this page's heading: step 1 match, read and confirmed by the reader
      r:=security.scholarship_page_match_v1(v_dup, c.url, 'page_heading', c.id);
      update pipeline.scholarship_page_candidates set admit_status='matched_held' where id=c.id;
      insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_dup,c.provider_id,'matched_held',r);
      return jsonb_build_object('admitted',false,'reason','held scholarship matched','scholarship_id',v_dup,'match',r);
    end if;
    update pipeline.scholarship_page_candidates set admit_status='duplicate', admit_reasons=array['already held'] where id=c.id;
    insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_dup,c.provider_id,'duplicate',jsonb_build_object('name',v_name));
    return jsonb_build_object('admitted',false,'reason','already held','scholarship_id',v_dup);
  end if;

  v_key:='scholarship:'||coalesce((select k.iso_alpha2 from catalogue.providers pp join ref.countries k on k.id=pp.country_id where pp.id=c.provider_id),'AU')||':first-party:'||replace(c.provider_id::text,'-','')||':'||md5(v_norm);
  v_id:=scholarship.deterministic_uuid(v_key);
  if exists (select 1 from scholarship.scholarships where id=v_id) then
    update pipeline.scholarship_page_candidates set admit_status='duplicate', admit_reasons=array['same stable key'] where id=c.id;
    return jsonb_build_object('admitted',false,'reason','same stable key','scholarship_id',v_id);
  end if;
  v_src:=security.coverage_sweep_source(c.provider_id);
  insert into pim.entity_registry(id,entity_type,stable_key,lifecycle_status) values (v_id,'scholarship',v_key,'active') on conflict (stable_key) do update set lifecycle_status='active', updated_at=now();
  insert into pipeline.evidence_artifacts(entity_id,source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata,capture_version,evidence_group_key)
  values (v_id, v_src, 'scholarship_page', v_url, c.storage_path, c.content_hash, 'application/gzip',
          jsonb_build_object('worker','coverage-sweep scholarship_discover','decision','CF-247 scholarship discovery (Decision 139 sweep)','candidate_id',c.id,'extractor',f->>'extractor'), 1, 'scholarship:'||v_id)
  returning id into v_ev;
  insert into scholarship.scholarships(id,stable_key,provider_id,name,scholarship_type,audience,source_url,lifecycle_status,publication_status,source_id,evidence_id,confidence,award_value_type,updated_at)
  values (v_id,v_key,c.provider_id,left(v_name,300),'provider_scholarship','international',v_url,'active','unpublished',v_src,v_ev,0.9,'text_only',now());
  insert into scholarship.identifiers(scholarship_id,scheme,identifier_value,source_id,evidence_id,is_primary,status)
  values (v_id,'first_party_detail_url',v_url,v_src,v_ev,true,'active') on conflict do nothing;
  insert into pipeline.scholarship_acquisition_trace(provider_id,observed_title,first_party_detail_url,scholarship_id,verification_evidence_id,stage,verification_status,observed_at,verified_at,updated_at,metadata)
  values (c.provider_id,left(v_name,300),v_url,v_id,v_ev,'canonical_unpublished','verified_first_party',c.found_at,now(),now(),
          jsonb_build_object('admission','security.scholarship_admit_from_provider_page_v1','candidate_id',c.id,'candidate_source',c.source,'rule','single named scholarship detail page on the provider site, explicitly open to international students, currently offered'));
  insert into pipeline.scholarship_pages(scholarship_id,url,url_source,candidate_id,final_url,read_status,http_status,fetched_via,read_at,next_read_at,attempts,evidence_id,facts,name_check)
  values (v_id,v_url,'admitted',c.id,c.final_url,'read',c.http_status,c.fetched_via,c.read_at,now()+interval '90 days',0,v_ev,f,jsonb_build_object('ok',true,'basis','admitted_from_page_title','heading',v_name));
  update pipeline.scholarship_page_candidates set admit_status='admitted', admitted_scholarship_id=v_id, admitted_at=now() where id=c.id;
  insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value,evidence_id) values (v_id,'admitted',null,jsonb_build_object('name',v_name,'url',v_url,'candidate_id',c.id),v_ev);
  v_apply:=security.scholarship_sweep_apply_v1(v_id);
  insert into pipeline.scholarship_admission_log(candidate_id,scholarship_id,provider_id,action,detail) values (c.id,v_id,c.provider_id,'admitted',jsonb_build_object('name',v_name,'url',v_url,'apply',v_apply));
  return jsonb_build_object('admitted',true,'scholarship_id',v_id,'apply',v_apply);
end $function$

security.scholarship_auto_publish_v1().def:
CREATE OR REPLACE FUNCTION security.scholarship_auto_publish_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '300s'
AS $function$
declare v_ids uuid[]; v_ref text; v_hold uuid[] := '{}';
begin
  if security.scholarship_setting('auto_publish', 0) < 1 then return jsonb_build_object('skipped', 'auto_publish is off'); end if;
  select coalesce(array_agg(p.scholarship_id), '{}') into v_ids
    from security.scholarship_publishability_v1() p join scholarship.scholarships s on s.id = p.scholarship_id
   where p.publishable and coalesce(s.publication_status, 'unpublished') <> 'published'
     and not exists (select 1 from security.layer4_search_blocked_scholarships b where b.scholarship_id = s.id);
  -- v2.15.248 (Platform Admin bugs 11/10-5, Fix 5): a scholarship published automatically that now fails a check is held with the
  -- reason and taken off search; it is listed in Layer 4 to release or fix. One a person published is shown as failing, not held.
  select coalesce(array_agg(p.scholarship_id), '{}') into v_hold
    from security.scholarship_publishability_v1() p join scholarship.scholarships s on s.id = p.scholarship_id
   where not p.publishable and s.publication_status = 'published'
     and not exists (select 1 from pipeline.scholarship_publication_holds h where h.scholarship_id = s.id and h.released_at is null)
     and coalesce((select b.approval_ref from pipeline.scholarship_publication_batches b where s.id = any (b.scholarship_ids) and b.kind = 'publish' order by b.created_at desc limit 1), '') like 'auto-publish%';
  v_ref := to_char(now() at time zone 'Australia/Melbourne', 'DD Mon YYYY HH24:MI');
  if cardinality(v_hold) > 0 then
    insert into pipeline.scholarship_publication_holds(scholarship_id, reason, held_by)
    select p.scholarship_id, 'Failed a check after publishing: ' || array_to_string(p.missing, '; '), 'auto' from security.scholarship_publishability_for_v1(v_hold) p
    on conflict (scholarship_id) do update set reason = excluded.reason, held_by = 'auto', held_at = now(), released_at = null, release_note = null;
    update scholarship.scholarships set publication_status = 'withdrawn', updated_at = now() where id = any (v_hold);
    insert into pipeline.scholarship_publication_batches(kind, approval_ref, scholarship_ids) values ('withdraw', 'auto-hold ' || v_ref, v_hold);
  end if;
  if cardinality(v_ids) > 0 then
    update scholarship.scholarships set publication_status = 'published', updated_at = now() where id = any (v_ids);
    insert into pipeline.scholarship_publication_batches(kind, approval_ref, scholarship_ids) values ('publish', 'auto-publish ' || v_ref, v_ids);
  end if;
  if cardinality(v_ids) + cardinality(v_hold) > 0 then
    insert into search.refresh_requests(requested_by) values ('auto-publish ' || v_ref || ': ' || cardinality(v_ids) || ' published, ' || cardinality(v_hold) || ' held');
  end if;
  return jsonb_build_object('published', cardinality(v_ids), 'held', cardinality(v_hold), 'batch', case when cardinality(v_ids) > 0 then 'auto-publish ' || v_ref end);
end $function$

security.scholarship_publication_review_.def:
CREATE OR REPLACE FUNCTION security.scholarship_publication_review_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
AS $function$
declare v_ids uuid[];
begin
  select coalesce(array_agg(s.id),'{}') into v_ids
    from scholarship.scholarships s join security.scholarship_publishability_v1() p on p.scholarship_id=s.id
   where s.publication_status='published' and not p.publishable;
  if cardinality(v_ids)>0 then
    update scholarship.scholarships set publication_status='withdrawn', updated_at=now() where id=any(v_ids);
    insert into pipeline.scholarship_publication_batches(kind,approval_ref,scholarship_ids) values ('withdraw','Decision 139 automatic withdrawal',v_ids);
  end if;
  return jsonb_build_object('withdrawn',cardinality(v_ids));
end $function$

security.scholarship_task_fire_v1(text[].def:
CREATE OR REPLACE FUNCTION security.scholarship_task_fire_v1(p_steps text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_step text; v_mode text; v_body jsonb; v_sent int := 0;
begin
  foreach v_step in array coalesce(p_steps, '{}') loop
    v_mode := case when v_step in ('discover', 'candidates') then 'scholarship_discover' else 'scholarship_read' end;
    v_body := case v_step
      when 'discover' then jsonb_build_object('mode', v_mode, 'phase', 'discover', 'limit', 6)
      when 'candidates' then jsonb_build_object('mode', v_mode, 'phase', 'candidates', 'read_limit', 30)
      else jsonb_build_object('mode', v_mode, 'limit', 40) end;
    if not exists (select 1 from pipeline.edge_request_log l where l.function_name = 'coverage-sweep' and l.mode = v_mode and l.created_at > now() - interval '45 seconds'
                    and not exists (select 1 from net._http_response r where r.id = l.request_id)) then
      perform pipeline.svc_pilot_submit_nonce('coverage-sweep', v_body);
      v_sent := v_sent + 1;
    end if;
  end loop;
  return v_sent;
end $function$

public.svc_scholarship_candidate_record(.def:
CREATE OR REPLACE FUNCTION public.svc_scholarship_candidate_record(p_candidate_id bigint, p_read_status text, p_http_status integer, p_fetched_via text, p_final_url text, p_storage_path text, p_sha256 text, p_facts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pipeline', 'security'
AS $function$
declare r jsonb; c pipeline.scholarship_page_candidates%rowtype; v_ev uuid; v_ai boolean := coalesce((select s.ai_admission from pipeline.scholarship_ai_extract_settings s where s.id=1),false) and exists (select 1 from pipeline.scholarship_ai_models m where m.status='active');
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  if p_read_status='deferred' then -- out of time in this run: back to the queue unchanged
    update pipeline.scholarship_page_candidates set leased_until=null, attempts=greatest(0,attempts-1) where id=p_candidate_id;
    return jsonb_build_object('admitted',false,'deferred',true);
  end if;
  update pipeline.scholarship_page_candidates set read_status=p_read_status, http_status=p_http_status, fetched_via=p_fetched_via, final_url=p_final_url,
         read_at=now(), leased_until=null, storage_path=coalesce(p_storage_path,storage_path), content_hash=coalesce(p_sha256,content_hash), facts=coalesce(p_facts,facts),
         next_read_at=case when p_read_status in ('read','robots_disallowed','gone') then now()+make_interval(days => security.pipeline_num_v1('reread.scholarship_candidate_days', 90)::int) else now()+make_interval(hours => security.pipeline_num_v1('retry.scholarship_candidate_failed_hours', 6)::int) end,
         admit_status=case when not v_ai and p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) is not true then 'rejected' else admit_status end,
         admit_reasons=case when not v_ai and p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) is not true
                            then array(select jsonb_array_elements_text(coalesce(p_facts->'admission'->'reasons','[]'))) else admit_reasons end
   where id=p_candidate_id;
  if not v_ai and p_read_status='read' and coalesce((p_facts->'admission'->>'admit')::boolean,false) then r:=security.scholarship_admit_from_provider_page_v1(p_candidate_id); end if;
  -- v2.15.249 (bugs 11/10-6): with AI admission on, the AI decides every page read (its copy is kept), not the rules
  if v_ai and p_read_status in ('read','too_thin') and p_storage_path is not null then
    insert into pipeline.scholarship_ai_queue(model_code,prompt_version,run_kind,candidate_id,provider_id,url)
    select a.model_code,a.prompt_version,'admit',p_candidate_id,(select x.provider_id from pipeline.scholarship_page_candidates x where x.id=p_candidate_id),coalesce(p_final_url,(select x.url from pipeline.scholarship_page_candidates x where x.id=p_candidate_id))
      from security.scholarship_ai_active_v1() a where not exists (select 1 from pipeline.scholarship_ai_queue q where q.candidate_id=p_candidate_id and q.state in ('queued','leased'));
    r:=jsonb_build_object('admitted',false,'ai','queued');
  end if;
  select * into c from pipeline.scholarship_page_candidates where id=p_candidate_id;
  -- v2.15.248 (Platform Admin bugs 11/10-5, Fix 2): a stored page that did not become a scholarship is kept as evidence of the decision
  if c.storage_path is not null and c.evidence_id is null and coalesce(c.admit_status,'')<>'admitted' then
    insert into pipeline.evidence_artifacts(source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata,capture_version,evidence_group_key)
    values (security.coverage_sweep_source(c.provider_id),'scholarship_candidate_page',coalesce(c.final_url,c.url),c.storage_path,c.content_hash,'application/gzip',
            jsonb_build_object('candidate_id',c.id,'provider_id',c.provider_id,'read_status',c.read_status,'decision',coalesce(c.admit_status,c.read_status),'reasons',to_jsonb(coalesce(c.admit_reasons,'{}'::text[])),'worker','coverage-sweep scholarship candidates'),1,'scholarship_candidate:'||c.id)
    returning id into v_ev;
    update pipeline.scholarship_page_candidates set evidence_id=v_ev where id=c.id;
  end if;
  -- (Fix 4) a page that lists scholarships is suggested as the provider's listing page, for a person to confirm
  if coalesce(c.admit_status,'')<>'admitted' and c.read_status in ('read','too_thin')
     and (coalesce(c.facts->>'h1','')||' '||coalesce(c.title,'')||' '||coalesce(c.facts->>'page_title','') ~* '(scholarships? (finder|search|list|directory)|grants and scholarships|find (a|your) scholarship|^\s*scholarships\s*$)'
          or coalesce(c.admit_reasons,'{}') && array['listing_page'] or c.url ~* '(scholarship-finder|/scholarships?/?$|/grants-scholarships/?$)') then
    insert into pipeline.scholarship_listing_pages(provider_id,url,url_norm,source,active,status)
    values (c.provider_id,coalesce(c.final_url,c.url),security.scholarship_url_norm(coalesce(c.final_url,c.url)),'suggested',false,'suggested')
    on conflict (provider_id,url_norm) do nothing;
  end if;
  return coalesce(r, jsonb_build_object('admitted',false));
end $function$

public.svc_scholarship_discover_record(u.def:
CREATE OR REPLACE FUNCTION public.svc_scholarship_discover_record(p_provider_id uuid, p_status text, p_site_origin text, p_method text, p_url_count integer, p_candidates jsonb, p_matches jsonb, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pipeline', 'security'
AS $function$
declare v_kept int; v_matched int:=0; m jsonb; r jsonb; v_cid bigint;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  insert into pipeline.scholarship_page_candidates(provider_id,url,url_norm,title,source)
  select p_provider_id, c->>'url', security.scholarship_url_norm(c->>'url'), nullif(left(c->>'title',300),''), coalesce(c->>'source','sitemap')
    from jsonb_array_elements(coalesce(p_candidates,'[]')) c
   where coalesce(c->>'url','') ~* '^https?://' and (security.url_on_provider_sites(c->>'url', p_provider_id) or security.url_on_provider_site(c->>'url', p_site_origin))
  on conflict (provider_id,url_norm) do update set title=coalesce(pipeline.scholarship_page_candidates.title, excluded.title);
  select count(*) into v_kept from pipeline.scholarship_page_candidates where provider_id=p_provider_id;
  update pipeline.scholarship_discovery_providers set status=p_status, site_origin=coalesce(p_site_origin,site_origin), method=p_method, url_count=p_url_count,
         kept_count=v_kept, discovered_at=now(), leased_until=null, last_error=p_error, updated_at=now() where provider_id=p_provider_id;
  for m in select * from jsonb_array_elements(coalesce(p_matches,'[]')) loop
    select id into v_cid from pipeline.scholarship_page_candidates where provider_id=p_provider_id and url_norm=security.scholarship_url_norm(m->>'url');
    if v_cid is null then continue; end if;
    if (select provider_id from scholarship.scholarships where id=(m->>'scholarship_id')::uuid) is distinct from p_provider_id then continue; end if;
    r:=security.scholarship_page_match_v1((m->>'scholarship_id')::uuid, m->>'url', m->>'basis', v_cid);
    if (r->>'matched')::boolean then v_matched:=v_matched+1; end if;
  end loop;
  update pipeline.scholarship_discovery_providers set matched_count=coalesce(matched_count,0)+v_matched where provider_id=p_provider_id;
  return jsonb_build_object('kept',v_kept,'matched',v_matched);
end $function$

public.svc_scholarship_read_record(uuid,.def:
CREATE OR REPLACE FUNCTION public.svc_scholarship_read_record(p_scholarship_id uuid, p_read_status text, p_http_status integer, p_fetched_via text, p_final_url text, p_storage_path text, p_sha256 text, p_facts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'scholarship', 'pipeline', 'security'
AS $function$
declare v_ev uuid; v_src uuid; v_pid uuid; v_url text; r jsonb; v_ai boolean := coalesce((select s.ai_admission from pipeline.scholarship_ai_extract_settings s where s.id=1),false) and exists (select 1 from pipeline.scholarship_ai_models m where m.status='active');
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role required'; end if;
  select s.provider_id, p.url into v_pid, v_url from scholarship.scholarships s join pipeline.scholarship_pages p on p.scholarship_id=s.id where s.id=p_scholarship_id;
  if p_storage_path is not null and p_read_status='read' then
    v_src:=security.coverage_sweep_source(v_pid);
    -- unchanged page: reuse its evidence; changed page: next capture version, superseding the previous one
    select e.id into v_ev from pipeline.evidence_artifacts e where e.evidence_group_key='scholarship:'||p_scholarship_id and e.content_hash=p_sha256 order by e.capture_version desc limit 1;
    if v_ev is null then
      insert into pipeline.evidence_artifacts(entity_id,source_id,evidence_type,source_url,storage_path,content_hash,mime_type,metadata,capture_version,evidence_group_key,supersedes_evidence_id)
      select p_scholarship_id, v_src, 'scholarship_page', coalesce(p_final_url,v_url), p_storage_path, p_sha256, 'application/gzip',
             jsonb_build_object('worker','coverage-sweep scholarship_read','decision','Decision 139 sweep'),
             coalesce((select max(e.capture_version) from pipeline.evidence_artifacts e where e.evidence_group_key='scholarship:'||p_scholarship_id),0)+1,
             'scholarship:'||p_scholarship_id,
             (select e.id from pipeline.evidence_artifacts e where e.evidence_group_key='scholarship:'||p_scholarship_id order by e.capture_version desc limit 1)
      returning id into v_ev;
    end if;
  end if;
  update pipeline.scholarship_pages set requested_at=case when p_read_status='waiting_scraper' then requested_at end, read_status=p_read_status, http_status=p_http_status, fetched_via=p_fetched_via, final_url=p_final_url,
         read_at=now(), leased_until=null, evidence_id=case when p_read_status='read' then coalesce(v_ev,evidence_id) else evidence_id end,
         -- v2.15.249: with AI admission on, an AI-read page keeps its AI facts; the rule-read facts are kept under 'rules'
         facts=case when p_read_status='read' then case when v_ai and facts->>'extracted_by'='ai' then facts || jsonb_build_object('rules', p_facts) else coalesce(p_facts,facts) end else facts end,
         name_check=case when p_facts ? 'name_check' then p_facts->'name_check' else name_check end,
         -- 11 Oct 2026: pages are read through the scraper only; one waiting for the scraper (no credit or service) is tried again
         -- within the hour and does not use up its attempts; a blocked page is tried again in 2 days
         next_read_at=case when p_read_status='read' then now()+make_interval(days => security.pipeline_num_v1('reread.scholarship_page_days', 90)::int)
                           when p_read_status='name_mismatch' then now()+make_interval(days => security.pipeline_num_v1('retry.scholarship_name_mismatch_days', 30)::int)
                           when p_read_status='blocked' then now()+make_interval(days => security.pipeline_num_v1('retry.scholarship_blocked_days', 2)::int)
                           when p_read_status='waiting_scraper' then now()+make_interval(hours => security.pipeline_num_v1('retry.scholarship_waiting_scraper_hours', 1)::int)
                           else now()+make_interval(hours => security.pipeline_num_v1('retry.scholarship_failed_hours', 6)::int) end,
         attempts=case when p_read_status='read' then 0 when p_read_status='waiting_scraper' then greatest(attempts-1,0) else attempts end
   where scholarship_id=p_scholarship_id;
  -- v2.15.249 (bugs 11/10-6): with AI admission on, the AI reads the page again and decides; the rules no longer withdraw or apply
  if p_read_status='read' and v_ai then
    insert into pipeline.scholarship_ai_queue(model_code,prompt_version,run_kind,scholarship_id,provider_id,url)
    select a.model_code,a.prompt_version,'reread',p_scholarship_id,v_pid,coalesce(p_final_url,v_url) from security.scholarship_ai_active_v1() a
     where not exists (select 1 from pipeline.scholarship_ai_queue q where q.scholarship_id=p_scholarship_id and q.state in ('queued','leased'));
    r:=jsonb_build_object('applied',false,'ai','queued');
  -- an admitted page that no longer meets the admission rules is withdrawn, not applied
  elsif p_read_status='read' and p_facts ? 'admission' and coalesce((p_facts->'admission'->>'admit')::boolean,true) is false
     and exists (select 1 from pipeline.scholarship_pages where scholarship_id=p_scholarship_id and url_source='admitted') then
    r:=security.scholarship_admission_withdraw_v1(p_scholarship_id, jsonb_build_object('reasons',p_facts->'admission'->'reasons','extractor',p_facts->>'extractor'));
  elsif p_read_status='read' then r:=security.scholarship_sweep_apply_v1(p_scholarship_id); end if;
  -- a discovered page that does not name the scholarship: the match is released (logged) so another page can be tried
  if p_read_status='name_mismatch' then
    update pipeline.scholarship_page_candidates c set match_basis='rejected_name_mismatch', matched_scholarship_id=null
      from pipeline.scholarship_pages sp where sp.scholarship_id=p_scholarship_id and sp.url_source='discovered' and c.id=sp.candidate_id;
    insert into pipeline.scholarship_sweep_changes(scholarship_id,field,before_value,after_value)
    select p_scholarship_id,'provider_page_rejected',jsonb_build_object('url',sp.url,'url_source',sp.url_source),p_facts->'name_check' from pipeline.scholarship_pages sp where sp.scholarship_id=p_scholarship_id;
  end if;
  return coalesce(r,jsonb_build_object('applied',false));
end $function$

public.svc_worker_report_v1(text,integer.def:
CREATE OR REPLACE FUNCTION public.svc_worker_report_v1(p_mode text, p_status integer, p_ms integer, p_body jsonb, p_worker text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id bigint; v_items int; v_failed int; v_ok int; v_landed jsonb;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  v_items := coalesce(security.worker_call_work_v1(p_body::text), 0)::int;
  v_failed := coalesce(nullif(p_body->>'failed', '')::int, nullif(p_body->'tally'->>'failed', '')::int, 0)
            + coalesce(nullif(p_body->'tally'->>'fetch_failed', '')::int, 0) + coalesce(nullif(p_body->'tally'->>'scrape_failed', '')::int, 0)
            + case when p_status >= 400 or coalesce(p_body->>'ok', 'true') = 'false' then 1 else 0 end;
  v_ok := greatest(0, coalesce(nullif(p_body->>'done', '')::int, nullif(p_body->>'applied', '')::int, v_items - v_failed));
  v_landed := coalesce(p_body->'landed', p_body->'tally', '{}'::jsonb);
  insert into pipeline.mode_outcome_ledger(mode, status, ms, items, ok, failed, landed, worker, detail)
  values (left(coalesce(p_mode, ''), 60), coalesce(p_status, 200), p_ms, v_items, v_ok, v_failed, v_landed, left(p_worker, 80),
          case when length((p_body - 'ok' - 'mode' - 'workerVersion' - 'tally' - 'landed')::text) <= 4000 then p_body - 'ok' - 'mode' - 'workerVersion' - 'tally' - 'landed'
               else jsonb_build_object('truncated', true, 'keys', (select jsonb_agg(k) from jsonb_object_keys(p_body) k)) end)  -- fixed: a row keeps at most 4 KB of detail
  returning id into v_id;
  return v_id;
end $function$
